/**
 * Publishes two demonstration field observations through the real pipeline —
 * the same normalise → summarise → project chain the portal runs when an
 * admin approves a dispatch. Nothing here is hand-written output: the prose,
 * the key facts and the chart are all generated by the shipped modules from
 * realistic field data.
 *
 *   node scripts/seed-field-demo.mjs            # publish
 *   node scripts/seed-field-demo.mjs --remove   # take them back down
 */

import { readFileSync, writeFileSync, mkdtempSync, unlinkSync } from 'node:fs';
import { homedir, tmpdir } from 'node:os';
import { join } from 'node:path';
import { execFileSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';
import { FS_BASE, accessToken, toValue } from './lib/firebase-rest.mjs';

const ROOT = new URL('..', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1');
const REMOVE = process.argv.includes('--remove');

/* Load the real pipeline modules (see verify-pipeline.mjs for why it bundles). */
const tmp = mkdtempSync(join(tmpdir(), 'iia-demo-'));
const entry = join(tmp, 'entry.ts');
const src = join(ROOT, 'apps', 'portal', 'src', 'repository').replace(/\\/g, '/');
writeFileSync(entry, `
export { normaliseDispatch } from '${src}/normalise';
export { draftPublicSummary } from '${src}/summarise';
export { toRepositoryRecord } from '${src}/publish';
`);
const bundle = join(ROOT, 'apps', 'portal', 'node_modules', '.iia-demo-seed.mjs');
execFileSync('npx', ['esbuild', entry, '--bundle', '--format=esm', '--platform=node',
  '--packages=external', `--outfile=${bundle}`, '--log-level=error'],
  { cwd: join(ROOT, 'apps', 'portal'), shell: process.platform === 'win32', stdio: 'inherit' });
const { normaliseDispatch, draftPublicSummary, toRepositoryRecord } = await import(pathToFileURL(bundle).href);

const base = {
  priority: 'routine', notes: '', teamMembers: '', sampleIds: '', safetyFlag: false,
  voiceUrl: null, imageUrls: [], csvUrl: null, docUrls: [], caption: '', status: 'approved',
  publisherName: 'Outreach desk', publisherUid: 'demo-publisher',
  platformCaptions: null, coverImageIndex: null, sopChecklist: null, adminNotes: null,
  createdAt: Date.now(), updatedAt: Date.now(),
};

const DISPATCHES = [
  {
    ...base,
    id: 'field-demo-maitri-ice',
    authorUid: 'demo', authorName: 'Dr A. Sharma',
    observedAt: Date.UTC(2026, 0, 22, 8, 0),
    station: 'Maitri', lat: -70.7659, lon: 11.7314, elevationM: 117,
    positionSource: 'GPS handheld',
    activity: 'Ice / glaciology survey',
    weather: { airTempC: -27, windSpeedKt: 32, windDir: 'NE', visibilityKm: 2, cloudOktas: 7, present: 'Blowing snow' },
    measurements: { siteId: 'MAI-S12', iceThickCm: '164', snowDepthCm: '22', freeboardCm: '11', surface: 'Wind slab' },
    notes: 'Stake MAI-S12 re-drilled, freeboard down 3 cm on last visit.',
    teamMembers: 'A. Sharma, K. Nair', sampleIds: 'ICE-2601-A',
  },
  {
    ...base,
    id: 'field-demo-bharati-penguins',
    authorUid: 'demo', authorName: 'Dr R. Iyer',
    observedAt: Date.UTC(2026, 0, 29, 11, 30),
    station: 'Bharati', lat: -69.4067, lon: 76.1913, elevationM: 25,
    positionSource: 'GPS handheld',
    activity: 'Wildlife observation',
    weather: { airTempC: -6, windSpeedKt: 11, windDir: 'SW', visibilityKm: 18, cloudOktas: 3, present: 'Partly cloudy' },
    measurements: { species: 'Pygoscelis adeliae', count: '340', lifeStage: 'Mixed', behaviour: 'Breeding', method: 'Direct count' },
    notes: 'First colony count of the season near the Larsemann Hills field camp.',
    teamMembers: 'R. Iyer, S. Bose',
  },
];

const token = await accessToken();

if (REMOVE) {
  for (const d of DISPATCHES) {
    const res = await fetch(`${FS_BASE}/publicArchive/${d.id}`, { method: 'DELETE', headers: { authorization: `Bearer ${token}` } });
    console.log(`  ${res.ok ? 'removed' : `HTTP ${res.status}`}  ${d.id}`);
  }
} else {
  let i = 0;
  for (const d of DISPATCHES) {
    const { dispatch: clean, measurements } = normaliseDispatch(d);
    const summary = draftPublicSummary(clean, measurements);
    const record = toRepositoryRecord(clean, summary, measurements, 'demo-admin',
      `IIA-2026-${String(1 + i++).padStart(4, '0')}`, d.observedAt);

    const res = await fetch(`${FS_BASE}/publicArchive/${record.id}`, {
      method: 'PATCH',
      headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
      body: JSON.stringify({ fields: toValue(record).mapValue.fields }),
    });
    console.log(`  ${res.ok ? 'ok     ' : `HTTP ${res.status}`}  ${record.metadata.identifier}  ${record.title}${record.chart ? `  [chart: ${record.chart.data.length} bars]` : ''}`);
    if (!res.ok) console.error(`         ${(await res.text()).slice(0, 200)}`);
  }
}

try { unlinkSync(bundle); } catch { /* already gone */ }
